 "content": "def transform(grid):
    # Each 3x3 block is background texture (0/5) with a marked cell; compress
    # the grid by retaining any non-background color in its corresponding block.
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w // 3)] for _ in range(h // 3)]
    for br in range(h // 3):
        for bc in range(w // 3):
            colors = [grid[r][c] for r in range(3*br, 3*br+3) for c in range(3*bc, 3*bc+3) if grid[r][c] not in (0, 5)]
            if colors:
                out[br][bc] = colors[0]
    return out
